/**
 * @module
 * Rate Limit Middleware for Hono.
 */

import type { Context } from '../../context'
import type { MiddlewareHandler } from '../../types'

interface RateLimitOptions {
  limit?: number
  windowMs?: number
  keyGenerator?: (c: Context) => string
  skip?: (c: Context) => boolean
  handler?: (c: Context) => Response | Promise<Response>
}

interface RateLimitEntry {
  count: number
  resetTime: number
}

const defaultKeyGenerator = (c: Context): string =>
  c.req.header('x-forwarded-for')?.split(',')[0].trim() ||
  c.req.header('x-real-ip') ||
  'unknown'

const defaultHandler = (c: Context): Response =>
  c.json({ error: 'Too Many Requests' }, 429)

/**
 * Rate Limit Middleware for Hono.
 *
 * @param {RateLimitOptions} [options] - The options for the rate limit middleware.
 * @param {number} [options.limit=100] - The maximum number of requests allowed within the window.
 * @param {number} [options.windowMs=60000] - The time window in milliseconds.
 * @param {Function} [options.keyGenerator] - A function to generate a unique key per client. Defaults to the remote IP.
 * @param {Function} [options.skip] - A function to determine whether to skip rate limiting for a given request.
 * @param {Function} [options.handler] - A custom handler invoked when the rate limit is exceeded. Defaults to a JSON 429 response.
 * @returns {MiddlewareHandler} The middleware handler function.
 *
 * @example
 * ```ts
 * const app = new Hono()
 *
 * app.use(rateLimit({ limit: 10, windowMs: 60_000 }))
 *
 * app.get('/', (c) => c.text('Hello!'))
 * ```
 */
export const rateLimit = (options?: RateLimitOptions): MiddlewareHandler => {
  const limit = options?.limit ?? 100
  const windowMs = options?.windowMs ?? 60000
  const keyGenerator = options?.keyGenerator ?? defaultKeyGenerator
  const skip = options?.skip
  const handler = options?.handler ?? defaultHandler

  const store = new Map<string, RateLimitEntry>()

  return async function rateLimit(c, next) {
    if (skip?.(c)) {
      return next()
    }

    const key = keyGenerator(c)
    const now = Date.now()
    let entry = store.get(key)

    if (!entry || entry.resetTime <= now) {
      entry = { count: 0, resetTime: now + windowMs }
      store.set(key, entry)
    }

    entry.count++

    if (entry.count > limit) {
      return handler(c)
    }

    await next()
  }
}

